{
  "per_column": [
    {
      "name": "intervention_type",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Categorises the goal's intervention area (cost, feedback, market, etc.), giving a genuine grouping axis to compare achievement rates. Samples map soundly to descriptions (cost reduction->cost_optimization, subscriptions->market_expansion)."
    },
    {
      "name": "action_mechanism",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "A finer mechanism categorisation partially overlapping intervention_type but offering more granularity. Mostly well-grounded; the 'workflow_redesign' for a cost-reduction-via-deduplication goal is a reasonable inference."
    },
    {
      "name": "technology_enablement",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Boolean flag for whether tech enables the goal; a plausible new axis for modelling achievement. Sample rows lacking tech mentions correctly marked False."
    },
    {
      "name": "baseline_stated",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Whether a numeric baseline is given (e.g. 78%->90%) is a strong measurability signal relevant to achievement. Sample values match presence/absence of stated baselines accurately."
    },
    {
      "name": "improvement_target_pct_range",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Bins the stated target magnitude; directly relevant to how ambitious/achievable a goal is. Grounded where a percent is present; Unknown correctly used when goal states absolute values not a pct."
    },
    {
      "name": "timeline_granularity",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.9,
      "hallucination_observed": false,
      "rationale": "Timeframe type is a solid grouping variable for achievement analysis and is well extracted from phrases like 'by end of Q4' and 'next fiscal year'."
    },
    {
      "name": "action_specificity",
      "analytical_usefulness": 0.75,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Single vs multi vs program-based action captures goal complexity, a reasonable predictor. Sample mappings (program->program_based, two levers->multi_action) are sound readings."
    },
    {
      "name": "metric_alignment",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.8,
      "hallucination_observed": false,
      "rationale": "Whether the assigned metric matches the goal intent is highly relevant, and the source shows clear mismatches (e.g. customer satisfaction goal tied to Expense Ratio) validating the flag. Judgement is somewhat subjective but well-founded."
    },
    {
      "name": "comparative_reference_type",
      "analytical_usefulness": 0.7,
      "source_groundedness": 0.85,
      "hallucination_observed": false,
      "rationale": "Reference baseline type (prior quarter/year) is a useful axis and overlaps partly with baseline_stated. 'compared to last quarter'->prior_quarter is correct; the fiscal-year sample's inference is reasonable."
    }
  ],
  "analytical_usefulness": 0.8,
  "source_groundedness": 0.87,
  "rationale": "The added columns collectively provide multiple genuinely distinct axes (intervention area, mechanism, timeline, target magnitude, measurability, metric alignment) that a downstream analyst could group and model against achievement. Some overlap exists (intervention_type vs action_mechanism; baseline_stated vs comparative_reference_type) but none are trivially redundant or near-constant. Values are sound readings of the source descriptions, with sensible extraction and appropriate Unknown/no_reference handling for silent rows; no hallucinations observed in the samples."
}
